'use strict';
const $=id=>document.getElementById(id),canvas=$('track'),ctx=canvas.getContext('2d');
const store={get(key,fallback){try{return localStorage.getItem(key)??fallback}catch{return fallback}},set(key,value){try{localStorage.setItem(key,value)}catch{}}};
let pilot=store.get('apex.pilot',''),state='login',lane=1,x=240,traffic=[],distance=0,elapsed=0,spawn=0,road=0,last=0,best=0;
const centers=[120,240,360],playerY=452;
function bestKey(){return 'apex.best.'+pilot.toLocaleLowerCase()}
function showReady(){state='ready';$('overlay').hidden=false;$('login-panel').hidden=true;$('ready-panel').hidden=false;$('pilot').textContent=pilot.toUpperCase();$('logout').hidden=false;best=Number(store.get(bestKey(),'0'))||0;$('best').textContent=best;$('pause').disabled=true;$('result-label').textContent='¿LISTO PARA SALIR?';$('result-title').textContent='Pisa a fondo.';$('result-text').textContent='Esquiva el tráfico. Cada metro cuenta.';$('start').textContent='Comenzar carrera →'}
$('login').addEventListener('submit',e=>{e.preventDefault();const value=$('name').value.trim();if(value.length<2){$('name').setCustomValidity('Escribe al menos 2 caracteres.');$('name').reportValidity();return}pilot=value;store.set('apex.pilot',pilot);showReady()});$('name').addEventListener('input',()=> $('name').setCustomValidity(''));
$('logout').onclick=()=>{state='login';pilot='';store.set('apex.pilot','');traffic=[];distance=0;$('score').textContent='0';$('best').textContent='0';$('speed').textContent='0';$('level').textContent='NIVEL 01';$('pilot').textContent='PILOTO SIN CONECTAR';$('logout').hidden=true;$('pause').disabled=true;$('pause').textContent='Ⅱ';$('overlay').hidden=false;$('login-panel').hidden=false;$('ready-panel').hidden=true;$('name').focus()};
function start(){if(state==='paused'){state='playing';$('overlay').hidden=true;$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pausar carrera');return}state='playing';lane=1;x=240;traffic=[];distance=0;elapsed=0;spawn=.7;road=0;$('score').textContent='0';$('overlay').hidden=true;$('pause').disabled=false;$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pausar carrera');last=performance.now()}
$('start').onclick=start;
function pause(){if(state==='paused'){start();return}if(state!=='playing')return;state='paused';$('overlay').hidden=false;$('result-label').textContent='TOMA UN RESPIRO';$('result-title').textContent='En pausa.';$('result-text').textContent='Tu carrera te espera en el mismo lugar.';$('start').textContent='Continuar →';$('pause').textContent='▶';$('pause').setAttribute('aria-label','Continuar carrera')}
$('pause').onclick=pause;
function move(dir){if(state==='playing')lane=Math.max(0,Math.min(2,lane+dir))}
$('left').onclick=()=>move(-1);$('right').onclick=()=>move(1);
document.addEventListener('keydown',e=>{if(e.target.matches('input'))return;const k=e.key.toLowerCase();if(['arrowleft','arrowright','a','d','p',' '].includes(k))e.preventDefault();if(e.repeat)return;if(k==='arrowleft'||k==='a')move(-1);if(k==='arrowright'||k==='d')move(1);if(k==='p'||k===' ')pause()});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pause()});window.addEventListener('blur',()=>{if(state==='playing')pause()});
function finish(){state='over';const score=Math.floor(distance),record=score>best;if(record){best=score;store.set(bestKey(),String(best))}$('best').textContent=best;$('overlay').hidden=false;$('pause').disabled=true;$('result-label').textContent=record?'NUEVO RÉCORD PERSONAL':'FIN DE LA CARRERA';$('result-title').textContent=score+' metros.';$('result-text').textContent=record?'Has superado tu marca. ¿Una vuelta más?':'El tráfico ganó esta vez. Vuelve a intentarlo.';$('start').textContent='Volver a correr →'}
function car(cx,cy,color,player=false){ctx.save();ctx.translate(cx,cy);ctx.fillStyle='#0008';ctx.fillRect(-28,-40,58,91);ctx.fillStyle='#070a07';for(const xx of [-29,21]){ctx.fillRect(xx,-25,9,21);ctx.fillRect(xx,21,9,21)}ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(-23,-43,46,86,9);ctx.fill();ctx.fillStyle='#16271f';ctx.beginPath();ctx.roundRect(-16,-22,32,25,4);ctx.fill();ctx.fillStyle='#ffffff30';ctx.fillRect(-14,-20,28,3);ctx.fillStyle='#122018';ctx.fillRect(-15,21,30,13);ctx.fillStyle='#f4ffe2';ctx.fillRect(-19,-39,10,5);ctx.fillRect(9,-39,10,5);ctx.fillStyle='#fa5044';ctx.fillRect(-20,36,10,4);ctx.fillRect(10,36,10,4);if(player){ctx.fillStyle='#f1ffc566';ctx.fillRect(-3,-41,6,18);ctx.fillRect(-3,4,6,16)}ctx.restore()}
function draw(){ctx.fillStyle='#182016';ctx.fillRect(0,0,480,560);ctx.fillStyle='#242a23';ctx.fillRect(58,0,364,560);ctx.fillStyle='#30372c';ctx.fillRect(65,0,350,560);ctx.fillStyle='#282f26';ctx.fillRect(72,0,336,560);for(let y=-80+road%80;y<560;y+=80){ctx.fillStyle='#a9c568';ctx.fillRect(54,y,5,40);ctx.fillRect(421,y,5,40);ctx.fillStyle='#4b5542';ctx.fillRect(178,y,4,36);ctx.fillRect(298,y,4,36);ctx.fillStyle='#455332';ctx.fillRect(27,y+10,4,19);ctx.fillRect(449,y+10,4,19)}ctx.fillStyle='#8c9a6c';ctx.fillRect(69,0,2,560);ctx.fillRect(409,0,2,560);for(const a of traffic)car(centers[a.lane],a.y,a.color);car(x,playerY,'#d3ff50',true)}
function tick(now){const dt=Math.min((now-last)/1000||0,.05);last=now;if(state==='playing'){elapsed+=dt;const speed=Math.min(420,190+elapsed*3);road+=speed*dt;distance+=speed*dt/11;x+=(centers[lane]-x)*Math.min(1,dt*18);spawn-=dt;if(spawn<=0){traffic.push({lane:Math.floor(Math.random()*3),y:-65,color:['#829bc0','#e68156','#b5b8a7','#b595c3'][Math.floor(Math.random()*4)]});spawn=Math.max(.85,1.5-elapsed*.008)}for(const a of traffic){a.y+=speed*dt;if(Math.abs(centers[a.lane]-x)<44&&Math.abs(a.y-playerY)<77){finish();break}}traffic=traffic.filter(a=>a.y<650);$('score').textContent=Math.floor(distance);$('speed').textContent=Math.round(speed*.55);$('level').textContent='NIVEL '+String(1+Math.floor(elapsed/15)).padStart(2,'0')}draw();requestAnimationFrame(tick)}
if(pilot)showReady();requestAnimationFrame(tick);
